if(req.url==='/api/diagnostics'&&req.method==='GET')return respond(res,200,{service:'Freddys V10',login:'authenticated',ai:{configured:!!process.env.OPENAI_API_KEY,liveProviderTest:'not_run',note:'Provider billing, quota and credentials require an authenticated upstream test'},voice:{configured:!!process.env.ELEVENLABS_API_KEY,liveProviderTest:'not_run'},anam:{configured:!!(process.env.ANAM_API_KEY&&process.env.ANAM_ADAM_PERSONA_ID),liveProviderTest:'not_run'},certifiedPicks:{configured:!!process.env.CERTIFIED_PICKS_FEED_URL,verifiedPredictions:0,certification:'HOLD'},recording:{browserDependent:true,serverTest:'not_run'},privacy:{passwordConfigured:true,secretValuesExposed:false}});
if(req.url==='/api/certified-picks'&&req.method==='GET'){const raw=process.env.CERTIFIED_PICKS_FEED_URL;if(!raw)return respond(res,503,{error:'CERTIFIED_PICKS_FEED_NOT_CONFIGURED',certifiedPredictions:0});let u;try{u=new URL(raw);if(u.protocol!=='https:'||u.username||u.password||u.port||!u.hostname.includes('.'))throw Error('bad url')}catch{return respond(res,503,{error:'CERTIFIED_PICKS_FEED_INVALID'})}const ctrl=new AbortController();const timeout=setTimeout(()=>ctrl.abort(),6000);try{const upstream=await fetch(u,{headers:{accept:'application/json',...(process.env.CERTIFIED_PICKS_FEED_TOKEN?{authorization:'Bearer '+process.env.CERTIFIED_PICKS_FEED_TOKEN}:{})},signal:ctrl.signal});if(!upstream.ok)return respond(res,502,{error:'CERTIFIED_PICKS_FEED_UNAVAILABLE',providerStatus:upstream.status});const content=await upstream.text();if(content.length>250000)return respond(res,502,{error:'CERTIFIED_PICKS_FEED_TOO_LARGE'});let payload;try{payload=JSON.parse(content)}catch{return respond(res,502,{error:'CERTIFIED_PICKS_FEED_NOT_JSON'})}return respond(res,200,{source:'configured_read_only_feed',verifiedByV10:false,data:payload})}catch{return respond(res,502,{error:'CERTIFIED_PICKS_FEED_UNREACHABLE'})}finally{clearTimeout(timeout)}}
if(req.url==='/api/converse'&&req.method==='POST'){if(!process.env.OPENAI_API_KEY)return respond(res,503,{error:'OPENAI_NOT_CONFIGURED'});const d=await body(req);if(!people[d.speaker]||typeof d.question!=='string'||d.question.length>3000)return respond(res,400,{error:'INVALID_REQUEST'});const role=people[d.speaker][1];const liveContext=await liveScoreboardContext();const response=await fetch('https://api.openai.com/v1/chat/completions',{method:'POST',headers:{authorization:'Bearer '+process.env.OPENAI_API_KEY,'content-type':'application/json'},body:JSON.stringify({model:process.env.OPENAI_MODEL||'gpt-4o-mini',max_tokens:240,messages:[{role:'system',content:'You are '+d.speaker+', '+role+' in Freddy’s Picks AI V10 private sports podcast. Give a precise spoken answer using the supplied model guide and available research. If data is missing, describe your specialty and what evidence is needed. Never invent live odds, injuries, game data, model probabilities or certified bets. Fresh public ESPN scoreboards are supplied separately and are real score/schedule data when their retrievedAt timestamp is recent. When scoreboard events are present, explicitly acknowledge the live scores and schedules you CAN see; never issue a blanket claim that no real-time sports data exists. Do not mislabel ESPN scores as real-time sportsbook odds, verified injury feeds, player-prop markets, or Champion-001 model probabilities. If all relevant ESPN sources failed, say exactly which sports feeds failed and when. Distinguish context from verified live betting data. CONTEXT: '+analystContext(d.speaker)+' LIVE SCOREBOARD: '+liveContext},{role:'user',content:d.question}]})});const j=await response.json().catch(()=>({}));if(!response.ok){console.error('V10_AI_PROVIDER_FAILURE',JSON.stringify({status:response.status,code:j?.error?.code||null,type:j?.error?.type||null,model:process.env.OPENAI_MODEL||'gpt-4o-mini'}));return respond(res,502,{error:'AI_PROVIDER_ERROR',providerStatus:response.status,category:response.status===401?'INVALID_OPENAI_CREDENTIAL':response.status===429?'OPENAI_QUOTA_OR_RATE_LIMIT':response.status===404?'OPENAI_MODEL_UNAVAILABLE':'OPENAI_UPSTREAM_FAILURE',providerCode:j?.error?.code||null});}return respond(res,200,{speaker:d.speaker,reply:j.choices?.[0]?.message?.content||'No response'})}
if(req.url==='/api/voice'&&req.method==='POST'){if(!process.env.ELEVENLABS_API_KEY)return respond(res,503,{error:'ELEVENLABS_NOT_CONFIGURED'});const d=await body(req);if(!people[d.speaker]||typeof d.text!=='string'||d.text.length>2000)return respond(res,400,{error:'INVALID_REQUEST'});const v=await fetch('https://api.elevenlabs.io/v1/text-to-speech/'+people[d.speaker][0],{method:'POST',headers:{'xi-api-key':process.env.ELEVENLABS_API_KEY,'content-type':'application/json',accept:'audio/mpeg'},body:JSON.stringify({text:d.text,model_id:'eleven_multilingual_v2',voice_settings:{...voiceProfiles[d.speaker],use_speaker_boost:true}})});if(!v.ok){console.error('V10_VOICE_PROVIDER_FAILURE',JSON.stringify({status:v.status,speaker:d.speaker}));return respond(res,502,{error:'VOICE_PROVIDER_ERROR',providerStatus:v.status,category:v.status===401?'INVALID_ELEVENLABS_CREDENTIAL':v.status===429?'ELEVENLABS_QUOTA_OR_RATE_LIMIT':'ELEVENLABS_UPSTREAM_FAILURE'});}res.writeHead(200,{'content-type':'audio/mpeg','cache-control':'no-store'});return res.end(Buffer.from(await v.arrayBuffer()))}
